import pytest
from intervals import merge_intervals


def test_vacio():
    assert merge_intervals([]) == []


def test_basico():
    assert merge_intervals([(1, 3), (2, 6), (8, 10), (15, 18)]) == [(1, 6), (8, 10), (15, 18)]


def test_se_tocan():
    assert merge_intervals([(1, 3), (3, 5)]) == [(1, 5)]


def test_desordenado_y_contenido():
    assert merge_intervals([(5, 7), (1, 10), (2, 3)]) == [(1, 10)]


def test_no_muta_entrada():
    data = [(3, 4), (1, 2)]
    merge_intervals(data)
    assert data == [(3, 4), (1, 2)]


def test_invalido():
    with pytest.raises(ValueError):
        merge_intervals([(5, 1)])


def test_devuelve_tuplas():
    out = merge_intervals([[1, 2], [2, 3]])
    assert out == [(1, 3)] and isinstance(out[0], tuple)

