def merge_intervals(intervals):
    items = [tuple(i) for i in intervals]
    for a, b in items:
        if a > b:
            raise ValueError("inicio > fin")
    items.sort()
    out = []
    for a, b in items:
        if out and a <= out[-1][1]:
            out[-1] = (out[-1][0], max(out[-1][1], b))
        else:
            out.append((a, b))
    return out
